from typing import List

class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)

        choose_sum = [0] * n
        row = [0] * k
        row[0] = 1

        for m in range(n):
            choose_sum[m] = sum(row) % MOD
            for j in range(min(k - 1, m + 1), 0, -1):
                row[j] = (row[j] + row[j - 1]) % MOD

        ans = 0
        for i, x in enumerate(nums):
            ans = (ans + x * (choose_sum[i] + choose_sum[n - 1 - i])) % MOD

        return ans
